const items = $input.all();
const existingIds = items.map(i => i.json['Video ID'] || '').filter(id => id !== '');
// Carry per-channel history for the 30-video baseline (Framework Part 1.1).
const history = items.map(i => ({
  ch: (i.json['Channel ID'] || '').toLowerCase().trim(),
  v: parseInt(i.json['View Count']) || 0,
  ts: i.json['Published At'] || ''
})).filter(h => h.ch);
console.log('[2x] Loaded ' + existingIds.length + ' existing Video IDs, ' + history.length + ' history rows');
const sources = $('1. Get Unbackfilled TikTok Sources').all();
return sources.map(s => ({ json: { ...s.json, _existing_ids: existingIds, _history: history } }));

const s = $input.first();
let raw = (s.json['TikTok_Handle'] || '').replace(/^@/, '').trim();
if (!raw) {
  const url = (s.json['TikTok_Links'] || '');
  const match = url.match(/tiktok\.com\/@([^/?]+)/);
  if (match) raw = match[1].trim();
}
const source_id = s.json.id || '';
const source_name = s.json['Source Name'] || '';
const existing_ids = s.json._existing_ids || [];
const history = s.json._history || [];
if (!raw) {
  console.log('[3a] No handle found for: ' + source_name + ', will mark backfilled and skip');
  return [{ json: { _skip: true, source_id, source_name, existing_ids, _history: history } }];
}
const profile = 'https://www.tiktok.com/@' + raw;
const sourceMap = {};
sourceMap[raw.toLowerCase()] = { source_id, source_name, handle: '@' + raw };
console.log('[3a] Processing source: ' + source_name + ' (' + profile + ')');
return [{ json: { profiles: [profile], source_map: sourceMap, source_id, source_name, existing_ids, _history: history } }];

const apifyInput = $('3a. Prepare Single Source Input').first().json;
const sourceMap = apifyInput.source_map || {};
const source_id = apifyInput.source_id;
const source_name = apifyInput.source_name;
const existing_ids = apifyInput.existing_ids || [];
const history = apifyInput._history || [];

const currentYear = new Date().getFullYear();
const currentYearStart = currentYear + '-01-01';

const allVideos = $input.all()
  .map(i => i.json)
  .filter(v => v && typeof v === 'object' && !v.error && (v.id || v.video_id));

console.log('[5] Apify returned ' + allVideos.length + ' videos for: ' + source_name);

if (!allVideos.length) {
  return [{ json: { _skip_videos: true, source_id, source_name } }];
}

const extracted = [];
for (const video of allVideos) {
  const publishedAt = video.createTimeISO || '';
  if (publishedAt && publishedAt < currentYearStart) {
    console.log('[5] Pre-' + currentYear + ' skip: ' + publishedAt);
    continue;
  }

  const authorHandle = (
    video['authorMeta.name'] || (video.authorMeta && video.authorMeta.name) || ''
  ).toLowerCase().trim();
  const sourceInfo = sourceMap[authorHandle] || { source_id, source_name, handle: '@' + authorHandle };
  const videoId = String(video.id || video.video_id || '');
  if (!videoId) continue;

  const parseNum = (val) => {
    if (val == null) return 0;
    const s = String(val).replace(/,/g, '').trim();
    if (s.endsWith('M')) return Math.round(parseFloat(s) * 1000000);
    if (s.endsWith('K')) return Math.round(parseFloat(s) * 1000);
    return parseInt(s) || 0;
  };

  const durationSec = parseInt(video['videoMeta.duration'] || (video.videoMeta && video.videoMeta.duration) || video.duration || 0);
  const title = video.text || video.desc || video.description || '';
  let tags = '';
  if (Array.isArray(video.hashtags)) {
    tags = video.hashtags.map(h => typeof h === 'string' ? h.replace(/^#/, '') : (h.name || h.title || '')).join(', ');
  } else if (video.text) {
    const found = video.text.match(/#[\w\u0080-\uFFFF]+/g);
    if (found) tags = found.map(h => h.replace(/^#/, '')).join(', ');
  }
  const url = video.webVideoUrl || 'https://www.tiktok.com/@' + authorHandle + '/video/' + videoId;

  extracted.push({
    video_id: videoId,
    source_id: sourceInfo.source_id,
    source_name: sourceInfo.source_name,
    handle: sourceInfo.handle,
    title, description: title, tags, url,
    view_count: parseNum(video.playCount),
    like_count: parseNum(video.diggCount),
    comment_count: parseNum(video.commentCount),
    share_count: parseNum(video.shareCount || 0),
    duration: durationSec,
    published_at: publishedAt,
    channel_id: authorHandle,
    content_type: 'TikTok',
    platform: 'TikTok'
  });
}

if (!extracted.length) {
  console.log('[5] No ' + currentYear + '+ videos for: ' + source_name);
  return [{ json: { _skip_videos: true, source_id, source_name } }];
}

// Per-creator baseline median over last 30 videos (Framework Part 1.1).
// OS = views / channel median over last 30 videos. Combines Video Library history
// (passed via _history) with this run's videos, newest 30 by date.
function median(arr) {
  if (!arr.length) return 0;
  const s = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 === 0 ? (s[mid - 1] + s[mid]) / 2 : s[mid];
}

const historyByChannel = {};
for (const h of history) {
  if (!historyByChannel[h.ch]) historyByChannel[h.ch] = [];
  historyByChannel[h.ch].push({ v: h.v, ts: h.ts });
}

const currentByChannel = {};
for (const v of extracted) {
  const ch = v.channel_id;
  if (!currentByChannel[ch]) currentByChannel[ch] = [];
  currentByChannel[ch].push({ v: v.view_count, ts: v.published_at });
}

const baselineByChannel = {};
const allChannels = new Set([...Object.keys(historyByChannel), ...Object.keys(currentByChannel)]);
for (const ch of allChannels) {
  const combined = [...(historyByChannel[ch] || []), ...(currentByChannel[ch] || [])]
    .filter(x => x.v > 0)
    .sort((a, b) => String(b.ts).localeCompare(String(a.ts)))
    .slice(0, 30)
    .map(x => x.v);
  baselineByChannel[ch] = median(combined);
}

console.log('[5] ' + source_name + ': ' + extracted.length + ' ' + currentYear + '+ videos scored against 30-video baseline');

return extracted.map(v => {
  const baseline = baselineByChannel[v.channel_id] || 0;
  const outlierScore = baseline > 0 ? parseFloat((v.view_count / baseline).toFixed(2)) : 0;
  return { json: { ...v, outlier_score: outlierScore, baseline_median: baseline, _existing_ids: existing_ids } };
});

// Gate 1 per AlfredAI Outlier & Relevance Scoring Framework: OS >= 2.0x
// Tiers: Mega-Viral (>5.0), Strong Outlier (2.0-5.0). Below 2.0 rejected.
const OUTLIER_THRESHOLD = 2.0;
const incomingItems = $input.all();

function tierFor(score) {
  if (score > 5.0) return 'Tier 1: Mega-Viral';
  if (score >= 2.0) return 'Tier 2: Strong Outlier';
  return null;
}

if (incomingItems.length === 1 && incomingItems[0].json._skip_videos) {
  const { source_id, source_name } = incomingItems[0].json;
  console.log('[6] No videos from Apify for: ' + source_name + ', marking backfilled anyway');
  return [{ json: { _skip: true, source_id, source_name } }];
}

const existingIds = new Set(incomingItems[0]?.json?._existing_ids || []);
const seenThisRun = new Set();
const outliers = [];
let skippedDupe = 0;
let skippedThreshold = 0;

for (const item of incomingItems) {
  if (item.json._skip_videos) continue;
  const vid = item.json.video_id;
  if (!vid || existingIds.has(vid) || seenThisRun.has(vid)) { skippedDupe++; continue; }
  seenThisRun.add(vid);
  const score = parseFloat(item.json.outlier_score) || 0;
  const tier = tierFor(score);
  if (tier) {
    outliers.push({ json: { ...item.json, is_outlier: true, outlier_tier: tier } });
  } else {
    skippedThreshold++;
  }
}

const source_id = incomingItems[0]?.json?.source_id || '';
const source_name = incomingItems[0]?.json?.source_name || '';

console.log('[6] Dupes: ' + skippedDupe + ' | Below 2.0x: ' + skippedThreshold + ' | Outliers: ' + outliers.length);

if (outliers.length === 0) {
  return [{ json: { _skip: true, source_id, source_name } }];
}

return outliers;

// Always pull source identity from 3a which is stable regardless of which path triggered us
let source_id = '';
let source_name = '';
try {
  const s = $('3a. Prepare Single Source Input').first().json;
  source_id = s.source_id || '';
  source_name = s.source_name || '';
} catch(e) {
  // fallback: try input items
  for (const item of $input.all()) {
    if (item.json.source_id) {
      source_id = item.json.source_id;
      source_name = item.json.source_name || '';
      break;
    }
  }
}
if (!source_id) {
  console.log('[10] No source_id found, skipping mark');
  return [];
}
const today = new Date().toISOString().split('T')[0];
console.log('[10] Preparing to mark backfilled: ' + source_name + ' (' + source_id + ')');
return [{ json: { source_id, source_name, last_scanned: today } }];

const items = $input.all();
if (!items.length) return [];

const source_id = items[0].json.source_id || '';
const source_name = items[0].json.source_name || '';

const toRecord = (v) => ({
  fields: {
    'Video ID': v.video_id,
    'Title': v.title,
    'URL': v.url,
    'Channel ID': v.channel_id,
    'Description': v.description,
    'Tags': v.tags,
    'Published At': v.published_at,
    'View Count': v.view_count,
    'Like Count': v.like_count,
    'Comment Count': v.comment_count,
    'Duration': v.duration,
    'Content Type': v.content_type,
    'Platform': v.platform,
    'Source Name': v.source_name,
    'Associated_Sources': v.source_id ? [v.source_id] : [],
    'Status': 'New',
    'Outlier Score': v.outlier_score || 0,
    'Outlier Tier': v.outlier_tier || '',
    'Creator_Handle': v.handle
  }
});

const chunks = [];
for (let i = 0; i < items.length; i += 10) {
  chunks.push(items.slice(i, i + 10).map(it => toRecord(it.json)));
}

console.log('[9a] ' + items.length + ' records -> ' + chunks.length + ' chunk(s) for: ' + source_name);

return chunks.map((records, idx) => ({
  json: { records, source_id, source_name, chunk: idx + 1, total_chunks: chunks.length }
}));

// All chunks done. Pass one signal to node 10.
const items = $input.all();
const source_id = $('9a. Chunk Records').first().json.source_id || '';
const source_name = $('9a. Chunk Records').first().json.source_name || '';
console.log('[9d] All chunks inserted for: ' + source_name);
return [{ json: { source_id, source_name } }];
